src='''def transform(grid):
    a=[row[:] for row in grid]; h,w=len(a),len(a[0]); bg=max(set(v for row in a for v in row),key=lambda v:sum(row.count(v) for row in a)); fg=next(v for row in a for v in row if v!=bg)
    for r in range(h):
        for c in range(1,w-1):
            if grid[r][c]==bg and grid[r][c-1]==fg and grid[r][c+1]==fg: a[r][c]=2
    for r in range(1,h-1):
        for c in range(w):
            if grid[r][c]==bg and grid[r-1][c]==fg and grid[r+1][c]==fg: a[r][c]=2
    return a
'''; open(p+'/task-e0f13981.py','w').write(src)
